<template><main class="qna-write-page"><div class="qna-write-shell page-shell"><button class="article-back" @click="router.push('/qna')"><i class="fa-solid fa-arrow-left"></i> 문의 목록</button><header><p class="eyebrow">NEW INQUIRY</p><h1>문의하기</h1><p>문의 내용을 자세히 남겨주시면 더욱 정확하게 답변해 드릴 수 있습니다.</p></header><div v-if="productName" class="qna-selected-product"><img :src="imagePath||'/img/defalut_product.png'" alt="문의 상품" /><div><small>문의 상품</small><strong>{{productName}}</strong></div></div><form @submit.prevent="submitQna"><label><span>문의 유형 *</span><select v-model="form.category"><option disabled value="">문의 유형을 선택하세요.</option><option>상품</option><option>주문</option><option>배송</option><option>결제</option><option>기타</option></select></label><label><span>제목 *</span><input v-model.trim="form.title" maxlength="100" placeholder="문의 제목을 입력하세요." /><small>{{form.title.length}} / 100</small></label><label><span>문의 내용 *</span><textarea v-model.trim="form.content" maxlength="2000" rows="10" placeholder="문의 내용을 자세히 입력해 주세요."></textarea><small>{{form.content.length}} / 2,000</small></label><p v-if="errorMessage" class="signup-error"><i class="fa-solid fa-circle-exclamation"></i>{{errorMessage}}</p><div class="qna-write-actions"><button type="button" @click="router.push('/qna')">취소</button><button type="submit" :disabled="!isValid||isSubmitting">{{isSubmitting?'등록 중...':'문의 등록'}}</button></div></form></div></main></template>
<script setup>import{computed,ref}from"vue";import{useRoute,useRouter}from"vue-router";import QnaService from"@/api/QnaService";const route=useRoute(),router=useRouter(),token=localStorage.getItem("token"),user=JSON.parse(localStorage.getItem("user")||"null"),productName=route.query.productName||"",imagePath=route.query.imagePath||"",isSubmitting=ref(false),errorMessage=ref("");const form=ref({title:"",content:"",category:"",orderId:route.query.orderId,productName,imagePath,userId:user?._id||""});const isValid=computed(()=>form.value.title&&form.value.content&&form.value.category);const submitQna=async()=>{if(!token||!user?._id){router.push("/login");return}if(!isValid.value)return;isSubmitting.value=true;errorMessage.value="";try{await QnaService.createQna(form.value,token);alert("문의가 등록되었습니다.");router.push("/qna")}catch(error){console.error(error);errorMessage.value=error.response?.data?.message||"문의를 등록하지 못했습니다."}finally{isSubmitting.value=false}};</script>
<style>.qna-write-page{padding:50px 0 110px;background:var(--color-warm)}.qna-write-shell{max-width:800px}.qna-write-shell>header{padding:35px 40px;background:#332c30;color:#fff}.qna-write-shell header h1{margin:7px 0;font-family:Georgia,"Noto Serif KR",serif;font-size:2.2rem;font-weight:400}.qna-write-shell header>p:last-child{color:#b1a6ab;font-size:.68rem}.qna-write-shell form{padding:35px 40px;background:#fff}.qna-write-shell form>label{position:relative;display:block;margin-bottom:22px}.qna-write-shell label>span{display:block;margin-bottom:7px;color:#5f565a;font-size:.7rem;font-weight:700}.qna-write-shell input,.qna-write-shell select,.qna-write-shell textarea{width:100%;padding:13px;border:1px solid #ddd5d8;border-radius:0;outline:0;background:#fff;font-size:.76rem}.qna-write-shell textarea{resize:vertical;line-height:1.7}.qna-write-shell input:focus,.qna-write-shell select:focus,.qna-write-shell textarea:focus{border-color:var(--color-brand)}.qna-write-shell label>small{display:block;margin-top:5px;color:#aaa1a5;text-align:right;font-size:.58rem}.qna-selected-product{display:flex;align-items:center;gap:15px;padding:18px 40px;border-bottom:1px solid var(--color-line);background:#fff}.qna-selected-product img{width:55px;height:55px;object-fit:contain;background:#f6f3f1}.qna-selected-product small,.qna-selected-product strong{display:block}.qna-selected-product small{color:#a49a9f;font-size:.58rem}.qna-selected-product strong{font-size:.76rem}.qna-write-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:30px}.qna-write-actions button{min-width:110px;padding:12px 20px;border:1px solid var(--color-brand);color:var(--color-brand);background:#fff;font-size:.72rem}.qna-write-actions button:last-child{color:#fff;background:var(--color-brand-dark)}.qna-write-actions button:disabled{opacity:.5}@media(max-width:600px){.qna-write-page{padding-top:30px}.qna-write-shell>header,.qna-write-shell form{padding:28px 20px}.qna-selected-product{padding-inline:20px}}
</style>
